std::vector<V> texture(std::vector<std::array<double,2>> centers,double radius=6){std::vector<V>m(1024);for(int y=0;y<32;y++)for(int x=0;x<32;x++){double dx=0,dy=0,best=1e10;for(auto c:centers){double ax=x+.5-c[0],ay=y+.5-c[1];ax-=std::round(ax/32)*32;ay-=std::round(ay/32)*32;if(std::hypot(ax,ay)<best){best=std::hypot(ax,ay);dx=ax;dy=ay;}}double t=acos(-1.)/2*(1-std::tanh((best-radius)/1.0)),p=std::atan2(dy,dx);m[x+y*32]={std::sin(t)*std::cos(p),std::sin(t)*std::sin(p),std::cos(t)};}return m;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("new CP output directory required");std::filesystem::path out=argv[1];if(std::filesystem::exists(out))throw std::runtime_error("output exists");std::filesystem::create_directories(out);UserConfig u;u.c.n={32,32,1};u.c.count=1024;u.c.h={4e-9,4e-9,3e-9};u.c.pbc={1,1,0};CurrentSOT d;Track track;double last=0,error=0;for(double cx:{30.5,31.5,.5,1.5}){auto m=texture({{cx,16.5}});auto o=observe_current(m,u,d,track,true);if(!o.single||!o.continuous)throw std::runtime_error("periodic observer single/continuity");if(last)error=std::max(error,std::abs(o.ux-last-4));last=o.ux;}
 if(error>1e-5)throw std::runtime_error("unwrap seam");auto single=texture({{10.5,16.5}},3.5),multi=texture({{8.5,16.5},{21.5,16.5}},3.5);Track fresh;auto first=observe_current(single,u,d,fresh,true);if(!first.single||!first.continuous)throw std::runtime_error("first single");auto bad=observe_current(multi,u,d,fresh,true);if(bad.cores!=2||!std::isfinite(bad.x)||bad.single||bad.continuous||fresh.has||fresh.continuous||std::isfinite(bad.ux))throw std::runtime_error("finite-center multicore must break continuity");
 DrivenState state;state.m={multi,multi};state.track={fresh,fresh};std::string id(64,'a');driven_cp(out/"invalid.bin",state,u,id);auto restored=restore_driven(out/"invalid.bin",u,id);for(int i=0;i<2;i++){auto invalid=observe_current(restored.m[i],u,d,restored.track[i],false);if(invalid.continuous||restored.track[i].has||restored.track[i].continuous)throw std::runtime_error("invalid CP restore");restored.m[i]=single;auto recovery=observe_current(single,u,d,restored.track[i],true);if(!recovery.single||recovery.continuous||!restored.track[i].has||restored.track[i].continuous)throw std::runtime_error("single recovery must retain invalid window");}
 driven_cp(out/"recovered.bin",restored,u,id);auto again=restore_driven(out/"recovered.bin",u,id);for(int i=0;i<2;i++){auto o=observe_current(again.m[i],u,d,again.track[i],false);if(!o.single||o.continuous||again.track[i].continuous)throw std::runtime_error("recovered CP cannot reset invalidity");}driven_cp(out/"recovered_roundtrip.bin",again,u,id);if(std::filesystem::file_size(out/"recovered.bin")!=244+48*1024)throw std::runtime_error("CP layout");
 std::vector<V>uniform(1024,V{0,0,1});auto zero=observe_current(uniform,u,d,track,true);if(std::isfinite(zero.x)||zero.single||track.continuous)throw std::runtime_error("zero Q invalidation");for(size_t k=0;k<uniform.size();k++)uniform[k]={0,0,k%2?1.:-1.};auto singular=observe_current(uniform,u,d,track,true);if(!singular.singular||singular.single)throw std::runtime_error("singular triangles invalidation");std::cout<<std::setprecision(17)<<"{\"passed\":true,\"Models\":0,\"fields\":0,\"unwrap_step_error_nm\":"<<error<<",\"finite_center_multicore_invalid\":true,\"invalid_and_recovered_CP_persistent\":true,\"zero_Q_invalid\":true,\"singular_invalid\":true}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
